// Pick exactly ONE eligible lead per pass through this loop, respecting THAT LEAD'S
// own local calling hours (9AM-9PM), based on their state.
//
// Priority 1: due follow-ups (Follow Up Date <= today, status was 'Follow-Up Requested')
// Priority 2: brand-new leads (Call Status empty)
// Excluded permanently: Booked, Not Interested, Do Not Call

const STATE_TZ = {
  AL:'America/Chicago', AK:'America/Anchorage', AZ:'America/Phoenix', AR:'America/Chicago',
  CA:'America/Los_Angeles', CO:'America/Denver', CT:'America/New_York', DE:'America/New_York',
  FL:'America/New_York', GA:'America/New_York', HI:'Pacific/Honolulu', ID:'America/Denver',
  IL:'America/Chicago', IN:'America/New_York', IA:'America/Chicago', KS:'America/Chicago',
  KY:'America/New_York', LA:'America/Chicago', ME:'America/New_York', MD:'America/New_York',
  MA:'America/New_York', MI:'America/New_York', MN:'America/Chicago', MS:'America/Chicago',
  MO:'America/Chicago', MT:'America/Denver', NE:'America/Chicago', NV:'America/Los_Angeles',
  NH:'America/New_York', NJ:'America/New_York', NM:'America/Denver', NY:'America/New_York',
  NC:'America/New_York', ND:'America/Chicago', OH:'America/New_York', OK:'America/Chicago',
  OR:'America/Los_Angeles', PA:'America/New_York', RI:'America/New_York', SC:'America/New_York',
  SD:'America/Chicago', TN:'America/Chicago', TX:'America/Chicago', UT:'America/Denver',
  VT:'America/New_York', VA:'America/New_York', WA:'America/Los_Angeles', WV:'America/New_York',
  WI:'America/Chicago', WY:'America/Denver'
};

const FULL_NAME_TO_ABBR = {
  ALABAMA:'AL', ALASKA:'AK', ARIZONA:'AZ', ARKANSAS:'AR', CALIFORNIA:'CA', COLORADO:'CO',
  CONNECTICUT:'CT', DELAWARE:'DE', FLORIDA:'FL', GEORGIA:'GA', HAWAII:'HI', IDAHO:'ID',
  ILLINOIS:'IL', INDIANA:'IN', IOWA:'IA', KANSAS:'KS', KENTUCKY:'KY', LOUISIANA:'LA',
  MAINE:'ME', MARYLAND:'MD', MASSACHUSETTS:'MA', MICHIGAN:'MI', MINNESOTA:'MN',
  MISSISSIPPI:'MS', MISSOURI:'MO', MONTANA:'MT', NEBRASKA:'NE', NEVADA:'NV',
  'NEW HAMPSHIRE':'NH', 'NEW JERSEY':'NJ', 'NEW MEXICO':'NM', 'NEW YORK':'NY',
  'NORTH CAROLINA':'NC', 'NORTH DAKOTA':'ND', OHIO:'OH', OKLAHOMA:'OK', OREGON:'OR',
  PENNSYLVANIA:'PA', 'RHODE ISLAND':'RI', 'SOUTH CAROLINA':'SC', 'SOUTH DAKOTA':'SD',
  TENNESSEE:'TN', TEXAS:'TX', UTAH:'UT', VERMONT:'VT', VIRGINIA:'VA', WASHINGTON:'WA',
  'WEST VIRGINIA':'WV', WISCONSIN:'WI', WYOMING:'WY'
};

function resolveAbbr(state) {
  const clean = (state || '').trim().toUpperCase();
  if (STATE_TZ[clean]) return clean;
  if (FULL_NAME_TO_ABBR[clean]) return FULL_NAME_TO_ABBR[clean];
  return clean;
}

function isWithinCallingHours(state) {
  const abbr = resolveAbbr(state);
  const tz = STATE_TZ[abbr] || 'America/New_York';
  const localHour = parseInt(
    new Date().toLocaleString('en-US', { timeZone: tz, hour: '2-digit', hour12: false }),
    10
  );
  return localHour >= 9 && localHour < 21;
}

const today = new Date();
today.setHours(0,0,0,0);

const rows = items.map(i => i.json);

const dueFollowUps = rows.filter(r => {
  if (r['Call Status'] !== 'Follow-Up Requested') return false;
  if (!r['Follow Up Date']) return false;
  const fu = new Date(r['Follow Up Date']);
  return fu <= today;
});

const freshLeads = rows.filter(r => !r['Call Status'] || r['Call Status'].trim() === '');

const candidates = [...dueFollowUps, ...freshLeads];

const inHoursLead = candidates.find(r => isWithinCallingHours(r['State']));

if (inHoursLead) {
  return [{ json: { status: 'hasLead', ...inHoursLead } }];
}

if (candidates.length > 0) {
  return [{ json: { status: 'waitingForHours' } }];
}

return [{ json: { status: 'noneLeft' } }];

const lead = $('Pick Next Eligible Lead').first().json;
const results = $input.first().json.organic_results || [];
const top = results[0] || {};

return [{
  json: {
    ...lead,
    competitor_name: top.title || 'a local competitor',
    competitor_detail: top.snippet ? top.snippet.slice(0, 180) : 'ranks on the first page for local roofing searches'
  }
}];

