const lead = $('Merge Opener Into Lead').first().json;
const call = $input.first().json;

return [{ json: { ...lead, vapi_call_id: call.id, poll_count: 0 } }];

const lead = $('Save Call ID').first().json;
const call = $input.first().json;
const pollCount = (lead.poll_count || 0) + 1;

return [{
  json: {
    ...lead,
    call_status: call.status,
    call_ended_reason: call.endedReason || null,
    call_summary: call.summary || '',
    call_transcript: call.transcript || '',
    poll_count: pollCount,
    timed_out: pollCount >= 20
  }
}];

