const lead = $('Merge Call Data').first().json;
const ai = $input.first().json;

let parsed;
try {
  parsed = JSON.parse(ai.choices?.[0]?.message?.content || '{}');
} catch (e) {
  parsed = {};
}

const outcome = lead.timed_out && lead.call_status !== 'ended'
  ? 'Call Timeout'
  : (parsed.outcome || 'No Answer');

return [{
  json: {
    ...lead,
    final_outcome: outcome,
    follow_up_date: parsed.follow_up_date || '',
    meeting_booked: parsed.meeting_booked || false,
    short_summary: parsed.short_summary || lead.call_summary
  }
}];
